/**
 * Binary min-heap. Used as the delayed-job calendar so scheduling
 * the next TTL expiry is O(log n) instead of scanning every record.
 */
export class MinHeap {
  constructor(compare) {
    this._compare = compare;
    this._items = [];
  }

  get size() {
    return this._items.length;
  }

  peek() {
    return this._items[0];
  }

  push(item) {
    this._items.push(item);
    this._bubbleUp(this._items.length - 1);
  }

  pop() {
    if (this._items.length === 0) {
      return undefined;
    }

    const top = this._items[0];
    const last = this._items.pop();
    if (this._items.length > 0) {
      this._items[0] = last;
      this._sinkDown(0);
    }
    return top;
  }

  _bubbleUp(index) {
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (this._compare(this._items[index], this._items[parent]) >= 0) {
        break;
      }
      swap(this._items, index, parent);
      index = parent;
    }
  }

  _sinkDown(index) {
    const length = this._items.length;
    while (true) {
      const left = index * 2 + 1;
      const right = left + 1;
      let smallest = index;
      if (left < length && this._compare(this._items[left], this._items[smallest]) < 0) {
        smallest = left;
      }
      if (right < length && this._compare(this._items[right], this._items[smallest]) < 0) {
        smallest = right;
      }
      if (smallest === index) {
        break;
      }
      swap(this._items, index, smallest);
      index = smallest;
    }
  }
}

function swap(items, i, j) {
  const tmp = items[i];
  items[i] = items[j];
  items[j] = tmp;
}

import { MinHeap } from "./heap.js";

/**
 * In-process job queue with a ready FIFO and a delayed min-heap.
 *
 * `enqueue` is synchronous and never waits on a worker, so request
 * handlers can fire-and-forget work (query logs, TTL expiry) without
 * adding latency. A background worker calls `dequeue`, which sleeps
 * until the next ready job or the next delayed job's `runAt`.
 */
export class JobQueue {
  constructor({ maxSize = 10_000 } = {}) {
    this.maxSize = maxSize;
    this.ready = [];
    this.delayed = new MinHeap((a, b) => a.runAt - b.runAt);
    this.waiters = [];
    this._timer = null;
    this._nextId = 1;
    this.enqueued = 0;
    this.dequeued = 0;
    this.dropped = 0;
  }

  get size() {
    return this.ready.length + this.delayed.size;
  }

  /**
   * @param {string} type
   * @param {object} [payload]
   * @param {{ delayMs?: number, dropIfFull?: boolean }} [options]
   * @returns {object | null} the job, or null if dropped under backpressure
   */
  enqueue(type, payload = {}, { delayMs = 0, dropIfFull = false } = {}) {
    if (dropIfFull && this.size >= this.maxSize) {
      this.dropped += 1;
      return null;
    }

    const job = {
      id: this._nextId++,
      type,
      payload,
      runAt: Date.now() + Math.max(0, delayMs),
      enqueuedAt: Date.now(),
    };

    this.enqueued += 1;
    if (delayMs > 0) {
      this.delayed.push(job);
      this._armTimer();
    } else {
      this._deliver(job);
    }
    return job;
  }

  /**
   * Wait for the next due job. Resolves with `null` when `signal` aborts
   * or `close()` is called.
   */
  dequeue(signal) {
    this.promoteDue();
    if (this.ready.length > 0) {
      this.dequeued += 1;
      return Promise.resolve(this.ready.shift());
    }
    if (signal?.aborted) {
      return Promise.resolve(null);
    }

    return new Promise((resolve) => {
      let settled = false;
      const finish = (job) => {
        if (settled) {
          return;
        }
        settled = true;
        signal?.removeEventListener("abort", onAbort);
        if (job) {
          this.dequeued += 1;
        }
        resolve(job);
      };

      const onJob = (job) => finish(job);
      const onAbort = () => {
        const index = this.waiters.indexOf(onJob);
        if (index !== -1) {
          this.waiters.splice(index, 1);
        }
        finish(null);
      };

      this.waiters.push(onJob);
      signal?.addEventListener("abort", onAbort, { once: true });
      if (signal?.aborted) {
        onAbort();
      }
    });
  }

  promoteDue(now = Date.now()) {
    while (this.delayed.size > 0 && this.delayed.peek().runAt <= now) {
      this._deliver(this.delayed.pop());
    }
    this._armTimer();
  }

  stats() {
    return {
      ready: this.ready.length,
      delayed: this.delayed.size,
      enqueued: this.enqueued,
      dequeued: this.dequeued,
      dropped: this.dropped,
    };
  }

  close() {
    if (this._timer) {
      clearTimeout(this._timer);
      this._timer = null;
    }
    const waiters = this.waiters.splice(0);
    for (const waiter of waiters) {
      waiter(null);
    }
  }

  _deliver(job) {
    const waiter = this.waiters.shift();
    if (waiter) {
      waiter(job);
    } else {
      this.ready.push(job);
    }
  }

  _armTimer() {
    if (this._timer) {
      clearTimeout(this._timer);
      this._timer = null;
    }
    if (this.delayed.size === 0) {
      return;
    }
    const wait = Math.max(0, this.delayed.peek().runAt - Date.now());
    this._timer = setTimeout(() => this.promoteDue(), wait);
    this._timer.unref?.();
  }
}

/**
 * Background worker: pulls jobs off the queue and runs the matching handler.
 * Failures are logged and swallowed so one bad job cannot stall the worker.
 */
export async function runWorker(queue, handlers, signal, logger) {
  while (!signal?.aborted) {
    const job = await queue.dequeue(signal);
    if (!job) {
      break;
    }

    const handler = handlers[job.type];
    if (!handler) {
      logger?.warn(`No handler registered for job type '${job.type}'`);
      continue;
    }

    try {
      await handler(job);
    } catch (error) {
      logger?.error(
        { err: error, jobId: job.id, jobType: job.type },
        "Background job failed",
      );
    }
  }
}

/**
 * Periodic producer: every `intervalSeconds`, enqueue a `ttl.sweep` job.
 * The worker performs the actual deletion so the timer callback stays cheap.
 */
export async function runSweepScheduler(queue, intervalSeconds, signal, logger) {
  if (intervalSeconds <= 0) {
    return;
  }

  logger?.info(`TTL sweep scheduler started (interval=${intervalSeconds}s)`);

  while (!signal?.aborted) {
    await sleep(intervalSeconds * 1000, signal);
    if (signal?.aborted) {
      break;
    }
    queue.enqueue("ttl.sweep");
  }

  logger?.info("TTL sweep scheduler stopped");
}

export function sleep(ms, signal) {
  return new Promise((resolve) => {
    if (signal?.aborted) {
      resolve();
      return;
    }

    const timer = setTimeout(resolve, ms);
    timer.unref?.();
    const onAbort = () => {
      clearTimeout(timer);
      resolve();
    };
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

export function createJobHandlers({ dnsService, queryLogs, logger } = {}) {
  return {
    "ttl.expire": async (job) => {
      const { hostname, type, value, expiresAt } = job.payload;
      const removed = dnsService.expireRecord(hostname, type, value, expiresAt);
      if (removed) {
        logger?.info(
          `TTL expire job removed ${type} ${hostname} -> ${value}`,
        );
      }
    },

    "ttl.sweep": async () => {
      const removed = dnsService.purgeExpired();
      if (removed) {
        logger?.info(`TTL sweep removed ${removed} expired record(s)`);
      }
    },

    "query.log": async (job) => {
      queryLogs.append(job.payload);
    },
  };
}

import { createJobHandlers } from "./handlers.js";
import { runSweepScheduler } from "./scheduler.js";
import { runWorker } from "./worker.js";

export { createJobHandlers } from "./handlers.js";
export { JobQueue } from "./queue.js";
export { runSweepScheduler } from "./scheduler.js";
export { runWorker } from "./worker.js";

/**
 * Start the worker pool and the TTL sweep scheduler.
 * Returns a promise that settles after `signal` is aborted and the queue is closed.
 */
export function startBackgroundJobs({
  queue,
  dnsService,
  queryLogs,
  sweepIntervalSeconds,
  concurrency = 1,
  signal,
  logger,
}) {
  const handlers = createJobHandlers({ dnsService, queryLogs, logger });
  const tasks = [];

  for (let i = 0; i < concurrency; i++) {
    tasks.push(runWorker(queue, handlers, signal, logger));
  }
  tasks.push(runSweepScheduler(queue, sweepIntervalSeconds, signal, logger));

  logger?.info(`Job workers started (concurrency=${concurrency})`);
  return Promise.all(tasks);
}

/**
 * Bounded in-memory ring buffer of DNS query log entries.
 * The HTTP path never writes here directly — a `query.log` worker does.
 */
export class QueryLogStore {
  constructor({ maxEntries = 10_000 } = {}) {
    this.maxEntries = maxEntries;
    this.entries = [];
    this._nextId = 1;
    this.accepted = 0;
    this.evicted = 0;
  }

  append(entry) {
    if (this.entries.length >= this.maxEntries) {
      this.entries.shift();
      this.evicted += 1;
    }
    this.entries.push({
      id: this._nextId++,
      ...entry,
    });
    this.accepted += 1;
    return this.entries[this.entries.length - 1];
  }

  list({ hostname, limit = 100 } = {}) {
    let queries = this.entries;
    if (hostname) {
      queries = queries.filter((entry) => entry.hostname === hostname);
    }
    const capped = Math.min(Math.max(1, limit), 1000);
    return {
      total: this.accepted,
      stored: this.entries.length,
      evicted: this.evicted,
      queries: queries.slice(-capped).reverse(),
    };
  }
}

