/**
 * Remove one record only if it has already expired. Used by the
 * per-record `ttl.expire` job so a later re-create of the same
 * (hostname, type, value) is not deleted early.
 */
removeIfExpired(hostname, type, value, expiresAtIso) {
  const records = this._records.get(hostname);
  if (!records) {
    return false;
  }

  const now = this.now();
  const index = records.findIndex((record) => {
    if (record.type !== type || record.value !== value) {
      return false;
    }
    if (!record.isExpired(now)) {
      return false;
    }
    if (expiresAtIso && record.expiresAt?.toISOString() !== expiresAtIso) {
      return false;
    }
    return true;
  });
  if (index === -1) {
    return false;
  }

  records.splice(index, 1);
  if (records.length === 0) {
    this._records.delete(hostname);
  }
  return true;
}

purgeExpired() {
  const now = this.now();
  let removed = 0;

  for (const [hostname, records] of this._records.entries()) {
    const kept = records.filter((record) => !record.isExpired(now));
    removed += records.length - kept.length;
    if (kept.length > 0) {
      this._records.set(hostname, kept);
    } else {
      this._records.delete(hostname);
    }
  }

  return removed;
}

