import Fastify from "fastify";

import {
  CLEANUP_INTERVAL_SECONDS,
  QUERY_LOG_MAX_ENTRIES,
  QUEUE_MAX_SIZE,
  WORKER_CONCURRENCY,
} from "./config.js";
import { DnsError } from "./errors.js";
import { JobQueue, startBackgroundJobs } from "./jobs/index.js";
import { QueryLogStore } from "./queryLog.js";
import analyticsRoutes from "./routes/analytics.js";
import dnsRoutes from "./routes/dns.js";
import { DnsService } from "./service.js";
import { DnsStore } from "./store.js";

export async function buildApp({
  store,
  queue,
  queryLogs,
  cleanupInterval,
  workerConcurrency,
  logger = true,
} = {}) {
  const dnsStore = store ?? new DnsStore();
  const jobQueue = queue ?? new JobQueue({ maxSize: QUEUE_MAX_SIZE });
  const queryLogStore = queryLogs ?? new QueryLogStore({ maxEntries: QUERY_LOG_MAX_ENTRIES });
  const dnsService = new DnsService(dnsStore, { queue: jobQueue });
  const interval =
    cleanupInterval === undefined ? CLEANUP_INTERVAL_SECONDS : cleanupInterval;
  const concurrency =
    workerConcurrency === undefined ? WORKER_CONCURRENCY : workerConcurrency;

  const app = Fastify({
    logger,
    ajv: {
      customOptions: {
        removeAdditional: false,
        coerceTypes: false,
        allErrors: true,
      },
    },
  });

  app.decorate("dnsStore", dnsStore);
  app.decorate("dnsService", dnsService);
  app.decorate("jobQueue", jobQueue);
  app.decorate("queryLogs", queryLogStore);

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof DnsError) {
      return reply.status(error.statusCode).send(error.toJSON());
    }

    if (error.validation || error.code === "FST_ERR_VALIDATION") {
      return reply.status(400).send({
        error: "VALIDATION_ERROR",
        message: "Request validation failed.",
        details: { errors: error.validation },
      });
    }

    request.log.error(error);
    return reply.status(500).send({
      error: "INTERNAL_ERROR",
      message: "An unexpected error occurred.",
    });
  });

  app.get("/health", async () => ({ status: "ok" }));

  await app.register(dnsRoutes);
  await app.register(analyticsRoutes);

  const abortController = new AbortController();
  let jobsPromise = Promise.resolve();

  app.addHook("onReady", async () => {
    jobsPromise = startBackgroundJobs({
      queue: jobQueue,
      dnsService,
      queryLogs: queryLogStore,
      sweepIntervalSeconds: interval,
      concurrency,
      signal: abortController.signal,
      logger: app.log,
    });
  });

  app.addHook("onClose", async () => {
    abortController.abort();
    jobQueue.close();
    await jobsPromise;
  });

  return app;
}

import { analyticsQueriesSchema } from "../schemas.js";
import { DnsValidationError } from "../errors.js";
import { normalizeHostname } from "../validators.js";

export default async function analyticsRoutes(fastify) {
  fastify.get("/api/analytics/queries", { schema: analyticsQueriesSchema }, async (request) => {
    const { hostname, limit: rawLimit } = request.query;
    const limit = parseLimit(rawLimit);
    const filter = hostname ? normalizeHostname(hostname) : undefined;

    return {
      queue: fastify.jobQueue.stats(),
      ...fastify.queryLogs.list({ hostname: filter, limit }),
    };
  });
}

function parseLimit(rawLimit) {
  if (rawLimit == null || rawLimit === "") {
    return 100;
  }
  const limit = Number(rawLimit);
  if (!Number.isInteger(limit) || limit < 1 || limit > 1000) {
    throw new DnsValidationError("Query parameter 'limit' must be an integer from 1 to 1000.", {
      limit: rawLimit,
    });
  }
  return limit;
}

