import assert from "node:assert/strict";
import { test } from "node:test";
import { setTimeout as delay } from "node:timers/promises";

import { MinHeap } from "../src/jobs/heap.js";
import { JobQueue } from "../src/jobs/queue.js";

test("min-heap pops in ascending runAt order", () => {
  const heap = new MinHeap((a, b) => a.runAt - b.runAt);
  heap.push({ runAt: 30 });
  heap.push({ runAt: 10 });
  heap.push({ runAt: 20 });
  assert.equal(heap.pop().runAt, 10);
  assert.equal(heap.pop().runAt, 20);
  assert.equal(heap.pop().runAt, 30);
  assert.equal(heap.pop(), undefined);
});

test("enqueue then dequeue returns the job", async () => {
  const queue = new JobQueue();
  const job = queue.enqueue("query.log", { hostname: "example.com" });
  const pulled = await queue.dequeue();
  assert.equal(pulled.id, job.id);
  assert.equal(pulled.type, "query.log");
  assert.equal(pulled.payload.hostname, "example.com");
  queue.close();
});

test("delayed jobs become ready after runAt", async () => {
  const queue = new JobQueue();
  queue.enqueue("ttl.expire", { hostname: "a.example.com" }, { delayMs: 40 });
  const start = Date.now();
  const job = await queue.dequeue();
  assert.ok(Date.now() - start >= 30);
  assert.equal(job.type, "ttl.expire");
  queue.close();
});

test("dropIfFull discards overflow instead of blocking", () => {
  const queue = new JobQueue({ maxSize: 2 });
  assert.ok(queue.enqueue("query.log", { n: 1 }, { dropIfFull: true }));
  assert.ok(queue.enqueue("query.log", { n: 2 }, { dropIfFull: true }));
  assert.equal(queue.enqueue("query.log", { n: 3 }, { dropIfFull: true }), null);
  assert.equal(queue.dropped, 1);
  assert.equal(queue.size, 2);
  queue.close();
});

test("TTL jobs are not dropped when the queue is full", () => {
  const queue = new JobQueue({ maxSize: 1 });
  queue.enqueue("query.log", { n: 1 }, { dropIfFull: true });
  const ttlJob = queue.enqueue("ttl.expire", { hostname: "x.example.com" });
  assert.ok(ttlJob);
  assert.equal(queue.size, 2);
  queue.close();
});

test("close unblocks a waiting dequeue", async () => {
  const queue = new JobQueue();
  const pending = queue.dequeue();
  queue.close();
  assert.equal(await pending, null);
});

test("abort signal unblocks a waiting dequeue", async () => {
  const queue = new JobQueue();
  const abort = new AbortController();
  const pending = queue.dequeue(abort.signal);
  abort.abort();
  assert.equal(await pending, null);
  queue.close();
