import assert from "node:assert/strict";
import { test } from "node:test";
import { setTimeout as delay } from "node:timers/promises";

import { DnsNotFoundError } from "../src/errors.js";
import { createJobHandlers, runWorker } from "../src/jobs/index.js";
import { JobQueue } from "../src/jobs/queue.js";
import { QueryLogStore } from "../src/queryLog.js";
import { DnsService } from "../src/service.js";
import { DnsStore } from "../src/store.js";

async function drain(queue, handlers, { count = 1, timeoutMs = 500 } = {}) {
  const abort = new AbortController();
  const worker = runWorker(queue, handlers, abort.signal);
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (queue.dequeued >= count) {
      break;
    }
    await delay(10);
  }
  abort.abort();
  queue.close();
  await worker;
}

test("ttl.expire job removes the matching expired record", async () => {
  const queue = new JobQueue();
  const service = new DnsService(new DnsStore(), { queue });
  const handlers = createJobHandlers({
    dnsService: service,
    queryLogs: new QueryLogStore(),
  });

  const record = service.addRecord("A", "expire.example.com", "10.0.0.9", 60);
  record.expiresAt = new Date(Date.now() - 1000);
  queue.enqueue("ttl.expire", {
    hostname: "expire.example.com",
    type: "A",
    value: "10.0.0.9",
    expiresAt: record.expiresAt.toISOString(),
  });

  await drain(queue, handlers, { count: 2 });
  assert.throws(() => service.resolve("expire.example.com"), DnsNotFoundError);
});

test("ttl.sweep job purges every expired record", async () => {
  const queue = new JobQueue();
  const service = new DnsService(new DnsStore(), { queue });
  const handlers = createJobHandlers({
    dnsService: service,
    queryLogs: new QueryLogStore(),
  });

  const first = service.addRecord("A", "gone.example.com", "10.0.0.1", 60);
  first.expiresAt = new Date(Date.now() - 1000);
  queue.enqueue("ttl.sweep");

  await drain(queue, handlers, { count: 2 });
  assert.throws(() => service.listRecords("gone.example.com"), DnsNotFoundError);
});

test("ttl.expire does not delete a newer record with the same tuple", async () => {
  const queue = new JobQueue();
  const service = new DnsService(new DnsStore(), { queue });
  const handlers = createJobHandlers({
    dnsService: service,
    queryLogs: new QueryLogStore(),
  });

  const stale = service.addRecord("A", "recycle.example.com", "10.0.0.2", 60);
  const staleExpiresAt = stale.expiresAt.toISOString();
  service.deleteRecord("recycle.example.com", "A", "10.0.0.2");
  service.addRecord("A", "recycle.example.com", "10.0.0.2", 60);

  queue.enqueue("ttl.expire", {
    hostname: "recycle.example.com",
    type: "A",
    value: "10.0.0.2",
    expiresAt: staleExpiresAt,
  });

  await drain(queue, handlers, { count: 3 });
  assert.deepEqual(service.resolve("recycle.example.com").resolvedIps, ["10.0.0.2"]);
});

test("resolve enqueues a query log without writing it inline", async () => {
  const queue = new JobQueue();
  const logs = new QueryLogStore();
  const service = new DnsService(new DnsStore(), { queue });
  const handlers = createJobHandlers({ dnsService: service, queryLogs: logs });

  service.addRecord("A", "example.com", "192.168.1.1");
  service.resolve("example.com");

  assert.equal(logs.entries.length, 0, "the request path must not write the log itself");
  await drain(queue, handlers, { count: 1 });
  assert.equal(logs.entries.length, 1);
  assert.equal(logs.entries[0].hostname, "example.com");
  assert.equal(logs.entries[0].found, true);
  assert.deepEqual(logs.entries[0].resolvedIps, ["192.168.1.1"]);
});

test("failed resolves are still logged asynchronously", async () => {
  const queue = new JobQueue();
  const logs = new QueryLogStore();
  const service = new DnsService(new DnsStore(), { queue });
  const handlers = createJobHandlers({ dnsService: service, queryLogs: logs });

  assert.throws(() => service.resolve("missing.example.com"), DnsNotFoundError);
  await drain(queue, handlers, { count: 1 });
  assert.equal(logs.entries[0].found, false);
  assert.equal(logs.entries[0].error, "NOT_FOUND");
});

test("omitting ttl creates a non-expiring record", () => {
  const service = new DnsService(new DnsStore());
  const record = service.addRecord("A", "example.com", "192.168.0.1");
  assert.equal(record.ttl, null);
  assert.equal(record.expiresAt, null);
  assert.deepEqual(service.resolve("example.com").resolvedIps, ["192.168.0.1"]);
});

